"use client"

import React from "react"
import { Tooltip, TooltipTrigger, TooltipContent } from "@/components/ui/tooltip"

interface TermDefinition {
	[key: string]: string
}

const glossary: TermDefinition = {
	"cti": "Cyber Threat Intelligence - analyzed, contextualized, and confidence-scored knowledge about adversaries that improves defensive decisions. The output of structured analytical processes applied to security data.",
	"passive-dns": "Passive DNS is a database of historical DNS resolution records collected from network traffic. Unlike active DNS queries, it doesn't involve querying nameservers directly and thus doesn't alert anyone that you're looking.",
	"iot": "Indicators of Compromise - observable artifacts that suggest a security compromise has occurred, such as file hashes, IP addresses, domains, or network patterns.",
	"ttp": "Tactics, Techniques, and Procedures - how attackers behave and operate. TTPs describe methods rather than specific tools, making them more persistent and harder to change than infrastructure.",
	"ttp-lower": "Tactics, Techniques, and Procedures - the methods, practices, and processes that attackers use. They describe behavior patterns rather than specific indicators.",
	"c2": "Command and Control - infrastructure used by attackers to communicate with and control compromised systems.",
	"malware": "Malicious software designed to harm, exploit, or gain unauthorized access to a computer or network.",
	"threat-actor": "An individual, group, or organization that conducts cyber attacks or other malicious activities.",
	"threat-hunting": "Proactive search through networks and systems to identify and isolate advanced threats that automated systems may have missed.",
	"infrastructure-pivoting": "The process of using one discovered indicator to find related infrastructure, such as using an IP address to find all domains that resolved to it.",
	"imphash": "Import hash - a hash of the import address table (IAT) in a Windows executable. More resilient than file hashing because it survives minor code modifications.",
	"jarm": "A method for creating fingerprints of TLS servers based on how they respond to probing. Used to identify malicious C2 servers.",
	"malleable-c2": "A feature in Cobalt Strike that allows operators to customize how their C2 beacons communicate, including User-Agent strings, URI patterns, and encryption methods.",
	"siem": "Security Information and Event Management - a system that collects, processes, and analyzes security logs and events from across an organization.",
	"mitre-att-ck": "A knowledge base of adversary tactics and techniques based on real-world observations. Used as a framework for understanding and categorizing threat behavior.",
	"t1027": "MITRE ATT&CK T1027: Obfuscated Files or Information - a defense evasion technique covering packing, encoding, or otherwise obscuring file content to evade detection (e.g. T1027.002: Software Packing).",
	"t1583": "MITRE ATT&CK T1583: Acquire Infrastructure - a resource development technique covering the purchase, lease, or rental of servers, domains, and other infrastructure used to support operations.",
	"t1071": "MITRE ATT&CK T1071: Application Layer Protocol - a command-and-control technique covering the use of standard protocols (HTTP, DNS, etc.) to blend C2 traffic with legitimate network activity (e.g. T1071.001: Web Protocols).",
	"t1547": "MITRE ATT&CK T1547: Boot or Logon Autostart Execution - a persistence technique covering registry keys, startup folders, and other mechanisms that automatically execute code when a system boots or a user logs on.",
	"t1003": "MITRE ATT&CK T1003: OS Credential Dumping - a credential access technique covering extraction of credentials from OS memory or storage (e.g. T1003.001: LSASS Memory, as used by tools like Mimikatz).",
	"t1566": "MITRE ATT&CK T1566: Phishing - an initial access technique covering delivery of malicious attachments or links to a victim, typically via email (e.g. T1566.001: Spearphishing Attachment).",
	"t1574": "MITRE ATT&CK T1574: Hijack Execution Flow - a persistence and defense evasion technique covering redirection of execution to attacker-controlled code, such as DLL sideloading (e.g. T1574.002: DLL Side-Loading).",
	"t1218": "MITRE ATT&CK T1218: System Binary Proxy Execution - a defense evasion technique covering the use of trusted, signed system binaries to execute attacker-controlled code and evade application controls.",
	"ssdeep": "A fuzzy hashing algorithm that can identify files that are similar but not identical. Useful for detecting slight variants of malware.",
	"upx": "Ultimate Packer for eXecutables - a tool that compresses executable files, changing their hash while maintaining functionality.",
	"vulnerability": "A weakness in software, hardware, or configuration that can be exploited by attackers to gain unauthorized access or cause harm.",
	"exploit": "Code or technique that takes advantage of a vulnerability to gain unauthorized access or execute arbitrary code.",
	"payload": "The code or data that is delivered to a target system, typically after successful exploitation.",
	"reconnaissance": "The gathering of information about a target system, network, or organization prior to launching an attack.",
	"lateral-movement": "The process of moving through a network from one compromised system to another to reach a final target or gain more access.",
	"persistence": "The ability of malware or an attacker to maintain access to a compromised system even after reboot or other disruption.",
	"privilege-escalation": "Gaining higher-level access or permissions on a system, typically from user-level to administrator or system-level.",
	"defense-evasion": "Techniques used by attackers to avoid detection by security controls, such as disabling antivirus or using obfuscation.",
	"exfiltration": "The unauthorized transfer of data from a compromised system to an external location controlled by the attacker.",
	"yara": "A tool and language for writing pattern-matching rules to identify malware and other suspicious content based on file signatures and behavioral patterns.",
	"sigma": "An open-source rule format for log detection that allows security teams to write detection rules once and apply them across multiple SIEM platforms.",
	"rat": "Remote Access Trojan - malware that allows an attacker to control a compromised system remotely, often used for persistence and lateral movement.",
	"mutex": "A synchronization object (mutual exclusion lock) that malware often uses to ensure only one instance runs at a time. Mutex names can become behavioral indicators.",
	"edr": "Endpoint Detection and Response - software that monitors endpoint systems for suspicious activity, collects telemetry, and can respond to threats automatically.",
	"xdr": "Extended Detection and Response - a correlation layer that ingests telemetry an EDR agent, an identity provider, an email gateway, and a cloud API already produce into one vendor's platform and links related alerts into a single incident timeline. It doesn't add a new vantage point of its own; it only correlates what its underlying sensors already collect, so a gap in one of those sensors is still a gap, just harder to notice under a unified UI.",
	"ndr": "Network Detection and Response - network monitoring that applies behavioral and machine-learning baselining to flow and traffic data instead of relying only on signature matching, flagging connections that deviate from a host's established pattern rather than ones that just match a known-bad rule. Shares the same encrypted-payload blind spot as signature-based NIDS, and needs a baselining period before its anomaly detection is reliable.",
	"soc": "Security Operations Center - the team responsible for monitoring systems, detecting security incidents, and responding to threats.",
	"tat": "Time to Acknowledge - the time it takes for a human to recognize and respond to an alert or security event.",
	"dwell-time": "The amount of time an attacker remains undetected within a compromised environment, typically measured in days.",
	"retrohunt": "The process of searching historical telemetry and logs for indicators or behavioral patterns to identify past compromises or activity.",
	"indicator-of-compromise": "Observable artifacts that suggest a security compromise has occurred, such as file hashes, IP addresses, domains, or network patterns.",
	"shodan": "A search engine for internet-connected devices that reveals services, software versions, and vulnerabilities by scanning IP addresses and ports.",
	"virustotal": "An online service that analyzes suspicious files and URLs against multiple antivirus engines and security tools to identify malware.",
	"shodan-cert-san": "Subject Alternative Names in TLS certificates - additional domains/IPs the certificate is valid for, often revealing co-hosted infrastructure.",
	"abuse-feeds": "Threat feeds that track known-malicious IP addresses, domains, and infrastructure reported by abuse.ch, AbuseIPDB, and similar services.",
	"censys": "A search engine that continuously scans the public internet and indexes the resulting host, service, and certificate data, similar in purpose to Shodan but built around its own scan infrastructure and a stronger certificate-search interface, useful for finding infrastructure that shares a fingerprint, port configuration, or certificate with a known-bad host.",
	"certificate-transparency": "A public, append-only log system (mandated by browser vendors) that every publicly trusted TLS certificate gets recorded in at issuance. Because the logs are queryable and can't be edited or deleted after the fact, they let an analyst search for every certificate ever issued for a domain or containing a specific string in its Subject Alternative Names, including ones an attacker later took offline, via tools like crt.sh.",
	"urlscan": "A service that visits a submitted URL in a real, instrumented browser and records everything observed: the final rendered page, every network request made, every domain and IP contacted, and a screenshot, turning a single suspicious link into a full picture of its infrastructure and behavior without the analyst's own browser ever touching it directly.",
	"greynoise": "A service that continuously monitors internet background noise, the constant baseline of scanning, probing, and exploitation attempts every public IP receives, and classifies which source IPs are known scanners, security research, or business tools rather than targeted attackers. Used to filter that noise out of an investigation so an analyst isn't chasing infrastructure that scans everyone.",
	"alienvault-otx": "AlienVault Open Threat Exchange, a free, community-contributed threat intelligence sharing platform where analysts publish 'pulses', bundles of indicators tied to a specific campaign or actor, complete with the context and reasoning behind them, letting a pivot start from someone else's already-organized findings instead of a single raw indicator.",
	"cobalt-strike": "A commercial adversary simulation and post-exploitation toolkit frequently used by threat actors for command and control and lateral movement.",
	"emotet": "A sophisticated banking trojan that evolved into a botnet and loader service, used by multiple threat actors for initial access and payload delivery.",
	"lockbit": "A ransomware operation and malware family known for fast encryption speeds and aggressive extortion tactics.",
	"qakbot": "A long-lived banking trojan family used primarily for credential theft and lateral movement, often deployed by affiliate groups.",
	"metasploit": "An open-source penetration testing framework providing exploit code, payloads, and post-exploitation tools commonly used by both attackers and defenders.",
	"mimikatz": "A widely-used post-exploitation tool for extracting credentials, tokens, and secrets from Windows systems and memory.",
	"apt41": "A Chinese-linked threat actor known for operations spanning espionage and financial cybercrime, targeting diverse sectors globally.",
	"fin7": "A financially-motivated threat actor group known for targeting retail and hospitality organizations for payment card theft and fraud.",
	"scattered-spider": "A threat actor group known for leveraging social engineering, compromised credentials, and living-off-the-land techniques for initial access.",
	"living-off-the-land": "Techniques that use legitimate built-in system tools (PowerShell, WMI, cmd.exe) instead of custom malware to avoid detection.",
	"dnsdb": "A passive DNS database that maintains historical DNS resolution records, useful for infrastructure investigation and pivoting.",
	"securitytrails": "A cybersecurity intelligence platform providing passive DNS, WHOIS history, and infrastructure reconnaissance data.",
	"riskiq": "A threat intelligence and digital risk management platform offering passive DNS, WHOIS, and certificate data for infrastructure analysis.",
	"zeromq": "ZeroMQ (also written as 0MQ or ZMQ) is a high-performance asynchronous messaging library used for building distributed and concurrent applications. It provides socket-like abstractions for message passing without requiring a dedicated message broker.",
	"salt-minion": "The Salt Minion is the agent daemon that runs on managed nodes. It connects outbound to the Salt Master over ZeroMQ, receives job broadcasts, executes them locally, and returns results.",
	"salt-master": "The Salt Master is the central orchestration server. It manages authentication, distributes configuration via Pillar, broadcasts execution jobs, and maintains the Event Bus.",
	"event-bus": "The Salt Event Bus is a real-time, ZeroMQ-backed publish-subscribe system running on the Master. Every action in Salt (jobs, minion auth, state runs) fires a tagged event that can be monitored and reacted to programmatically.",
	"reactor-system": "The Salt Reactor is a subsystem that watches the Event Bus for specific event tags and triggers pre-defined responses (states, runners, or commands) automatically, enabling autonomous infrastructure remediation.",
	"salt-pillar": "Salt Pillar is a secure, Master-side data store for distributing sensitive or targeted configuration (passwords, API keys, per-environment values) to specific Minions. Each Minion only receives the Pillar data explicitly assigned to it.",
	"salt-grains": "Grains are static data about a Minion host, collected at startup. They include OS type, kernel version, IP addresses, CPU architecture, and can be extended with custom values. Grains are used for targeting and conditional logic in states.",
	"salt-state": "A Salt State (.sls file) is a declarative YAML document that describes the desired configuration of a system. Salt ensures the system matches the declared state, only making changes when necessary (idempotency).",
	"salt-runner": "Salt Runners are modules that execute on the Master itself rather than on Minions. They are used for orchestration tasks, cloud provisioning, job management, and event monitoring.",
	"salt-returner": "Salt Returners allow Minion job results to be sent directly to external datastores (Redis, MySQL, Elasticsearch, Splunk) instead of or in addition to being returned to the Master.",
	"salt-syndic": "The Salt Syndic is a proxy master that sits between Minions and a higher-level Master, enabling tiered architectures for managing very large or geographically distributed fleets.",
	"salt-proxy-minion": "A Salt Proxy Minion is a special Minion process that runs on behalf of devices that cannot run the Salt agent natively (network switches, routers, IoT devices), translating Salt commands into device-specific APIs.",
	"salt-beacon": "Salt Beacons are Minion-side monitors that watch for specific local events (file changes, service crashes, load spikes) and fire events onto the Master Event Bus, enabling real-time reactive automation.",
	"salt-ssh": "Salt SSH (salt-ssh) is an agentless transport mode that executes Salt commands over standard SSH connections. It bundles Salt modules into a thin payload, copies it to the target, runs it, and returns the output without requiring a persistent Minion daemon.",
	"infrastructure-as-code": "Infrastructure as Code (IaC) is the practice of managing and provisioning infrastructure through machine-readable definition files rather than manual processes, enabling version control, repeatability, and auditability.",
	"idempotency": "Idempotency is the property where applying an operation multiple times produces the same result as applying it once. In configuration management, an idempotent state only makes changes when the system deviates from the desired configuration.",
	"highstate": "Highstate (state.highstate or state.apply) is the Salt command that applies all states defined in the top.sls file to the targeted Minions, bringing them into compliance with their declared configuration.",
	"jinja": "Jinja is a Python-based templating engine used in Salt state files to insert dynamic values, conditionals, and loops into YAML configuration. It enables states to adapt based on Grains, Pillar data, or other runtime context.",
	"ach": "Analysis of Competing Hypotheses - a structured analytic technique developed by Richards Heuer. The analyst lists all plausible hypotheses, scores each piece of evidence against every hypothesis, and selects the hypothesis with the least inconsistent evidence rather than the most consistent.",
	"structured-analytic-techniques": "Structured Analytic Techniques (SATs) - documented methods that externalize an analyst's reasoning so it can be examined, challenged, and reproduced. They reduce the impact of cognitive bias by forcing decomposition and visualization of the problem.",
	"analytic-judgment": "An analytic judgment is the actual product of intelligence analysis: an assessment paired with an explicit confidence level, the key evidence behind it, the assumptions it rests on, and the gaps that remain.",
	"confirmation-bias": "The tendency to seek, weight, and remember evidence that supports an existing hypothesis while discounting evidence that contradicts it. One of the most damaging biases in intelligence analysis.",
	"anchoring-bias": "The tendency to rely too heavily on the first piece of information received. In analysis, an early hypothesis becomes the anchor that all later evidence is interpreted around.",
	"mirror-imaging": "Assuming that an adversary thinks, values, and decides the way you do. Adversaries operate under different constraints, incentives, and doctrine, so the most logical path from your perspective is often not theirs.",
	"mental-model": "An experience-based internal representation of how some part of the world works. Mental models let analysts process information quickly, but unexamined models quietly filter what the analyst is able to perceive.",
	"all-source": "Analysis that fuses every available collection discipline and data type on a subject rather than specializing in one source. CTI is all-source by necessity, combining malware analysis, infrastructure data, victimology, and open sources.",
	"kill-chain": "A model that breaks an intrusion into sequential phases an adversary must complete to succeed. Interrupting any phase breaks the chain. Popularized for network defense by Lockheed Martin's Intrusion Kill Chain paper (2011).",
	"diamond-model": "The Diamond Model of Intrusion Analysis structures every intrusion event around four vertices: adversary, capability, infrastructure, and victim. It states its axioms explicitly and supports pivoting and clustering across events.",
	"false-flag": "An operation deliberately crafted to be attributed to someone else, for example by planting another group's tooling artifacts, language strings, or infrastructure patterns in an intrusion.",
	"osint": "Open-Source Intelligence - intelligence collection from publicly available sources such as websites, public records, social media, and published reporting.",
	"humint": "Human Intelligence - intelligence collected through interpersonal contact, the classic domain of case officers and informants.",
	"sigint": "Signals Intelligence - intelligence derived from intercepted signals and communications.",
	"diagnosticity": "The degree to which a piece of evidence helps distinguish between competing hypotheses. Evidence consistent with every hypothesis has zero diagnosticity no matter how compelling it feels.",
	"behavioral-analytic": "A detection encoded around adversary behavior rather than specific artifacts: the chain of actions an intrusion performs, expressed so it fires on new campaigns with entirely new infrastructure. Durable where indicators expire, and it carries context in the alert itself.",
	"indicator-lifecycle": "The cycle an indicator moves through: revealed (discovered or reported), vetted through retro-hunting, deployed to detection and mitigation, fired against real activity, and analyzed, which reveals new indicators that restart the cycle.",
	"key-indicator": "An indicator that remains consistent across multiple intrusions, uniquely distinguishes one activity cluster from others, separates malicious from benign activity, and aligns to a specific phase of adversary action. The small subset of indicators worth long-term investment.",
	"alert-fatigue": "The operational failure state where alert volume exceeds what analysts can triage, so genuinely critical alerts receive the same shallow treatment as noise. Usually caused by deploying unvetted indicators as a primary detection layer.",
	"detection-engineering": "The discipline of turning knowledge about adversary behavior into tested, maintained detection logic: Sigma rules, SIEM correlations, EDR policies, and the pipelines that validate they still fire.",
	"correlation": "Requiring multiple, independently weak signals to co-occur before treating them as a meaningful event, rather than alerting on any single one. A new-country sign-in alone is weak evidence; the same sign-in immediately followed by an MFA registration change is much stronger, even though neither event alone would justify a high-priority alert.",
	"risk-based-alerting": "Scoring individual signals and accumulating risk per entity (a user, a host, a role) instead of treating every detection rule as a binary fire-or-don't-fire alert, so a SOC can triage one elevated-risk identity with several moderate signals as a single prioritized case instead of many disconnected low-priority tickets.",
	"assume-role": "An AWS Security Token Service (STS) API call that lets a principal temporarily take on the permissions of an IAM role, issuing short-lived credentials scoped to that role. Legitimate and constant in normal cloud operations, which is exactly why a suspicious AssumeRole detection has to key on unusual context (a role never assumed before, an unfamiliar source) rather than the call itself.",
	"anomaly-detection": "An environmental detection approach that models normal activity statistically and alerts on deviation. It can catch novel activity nobody encoded, but its alerts arrive without context: the model knows something is unusual, not what it is or what to do.",
	"collection-management-framework": "A Collection Management Framework (CMF) maps every data source to what it can observe, which phases of adversary activity it covers, what follow-on collection it enables, how long it retains data, and who owns access. It exists to answer one question: which intelligence requirements can this organization actually satisfy?",
	"intelligence-requirement": "A single, simply worded question about the threat or the operational environment that fills a knowledge gap and supports a specific decision. Intelligence requirements drive the entire intelligence process; work without one is a hobby.",
	"priority-intelligence-requirement": "An intelligence requirement designated critical to a mission or decision, usually time-bound and tied to a specific event such as an acquisition, a product launch, or an active incident. PIRs change as the organization's immediate concerns change.",
	"collection-gap": "A question the organization cannot answer because the data that would answer it is not collected, not retained long enough, or not accessible. Documented gaps with the requirement that exposed them attached are the strongest funding argument a CTI team has.",
	"data-source": "In MITRE ATT&CK terms, a category of information a sensor or log can provide (such as Process Creation or Network Connection Creation), broken into data components. Data sources give teams a shared vocabulary for what a given telemetry source can actually see at technique level.",
	"courses-of-action": "The set of responses a defender can take against an adversary action, organized as a matrix of kill chain phases against seven categorical actions: discover, detect, deny, disrupt, degrade, deceive, and destroy. The defensive mirror of the kill chain, from the Lockheed Martin Intelligence-Driven CND paper.",
	"intelligence-gain-loss": "The intelligence-community concept that every action against an adversary has both a gain (what you learn) and a loss (what you forgo observing, plus what the action reveals to the adversary). Blocking an indicator mitigates a threat but signals to the adversary that the resource is burned, an intelligence loss the reflex overlooks.",
	"sinkhole": "Redirecting adversary infrastructure, usually a domain, to a defender-controlled server so that malware beacons reach an observer instead of the real controller. A sinkhole can measure a botnet, identify victims, or send benign commands, all while the malware believes it reached its operator.",
	"honeypot": "A deliberately exposed system or service designed to be attacked, so defenders can observe adversary behavior in a controlled environment. In the courses-of-action sense, redirecting C2 to a honeypot is a deception action rather than a denial.",
	"passive-defense": "Defensive actions that do not interfere with the adversary and carry no strategic cost: historically searching for whether an indicator appeared before (discover) and alerting if it appears again (detect). Passive actions compose freely and should be applied to nearly every indicator.",
	"threat-model": "A documented, prioritized picture of which threats plausibly apply to a specific organization, built from its crown jewels outward to the adversaries those assets attract. A threat model is the filter that lets a team ignore the threats that are not theirs.",
	"crown-jewels": "The assets an organization most needs to protect because their loss would cause the greatest harm: proprietary data or models, sensitive customer data, and the availability of business-critical systems. In threat modeling, the crown jewels are the starting point, not the adversary.",
	"target-centric-analysis": "An approach to intelligence analysis developed by Robert M. Clark in which all participants contribute to and draw from a shared, continuously updated conceptual model of a target, rather than passing products down a linear pipeline. It reduces stovepiping and makes intelligence gaps visible.",
	"systems-analysis": "The deliberate construction of the mental models, templates, and prototypes used to reason about a system. A full systems analysis examines an entity's structure, technologies, people, and tasks, plus the internal and external forces that change it. Threat modeling is the threat-focused subset of a systems analysis.",
	"cia-triad": "Confidentiality, Integrity, and Availability: the three properties of information a defender protects and an adversary attacks. Mapping a crown jewel to the CIA property most at risk clarifies which adversaries would target it and why.",
	"tip": "Threat Intelligence Platform - a system for storing, correlating, and sharing indicators and the analysis behind them. A TIP does not produce intelligence; it operationalizes intelligence that was already produced, making it searchable and queryable by other tools via API.",
	"misp-event": "In MISP, the container object everything is built around. A report read, a sample analyzed, or an incident tracked each becomes one event, holding a group of attributes plus whatever tags and galaxy clusters classify it.",
	"misp-attribute": "In MISP, an individual piece of data attached to an event: a hash, domain, IP, URL, or explanatory text. Each attribute carries a category (how it was used, e.g. payload delivery) and a type (what it is, e.g. sha256), and identical attributes across events are automatically highlighted for correlation.",
	"sighting": "A MISP mechanism for recording that an attribute was actually observed, true positive or false positive, each time an analyst encounters it. Sightings let an indicator's reliability change over time based on real usage instead of staying frozen at whatever confidence it had on ingest.",
	"misp-galaxy": "A MISP classification layer above tags: a cluster of related values, such as named threat actors or malware families, that can itself hold attributes and notes. Galaxies are built for tracking actors, tools, and TTPs across events, where a plain tag only labels a single event.",
	"tlp": "Traffic Light Protocol - a four-color classification (RED, AMBER, GREEN, WHITE/CLEAR) that tells the recipient of shared intelligence how far they are allowed to redistribute it. TLP travels with the data itself, commonly as a tag in a TIP, so the sharing restriction survives every hop.",
	"defanging": "The practice of altering a malicious URL, domain, or IP address, for example by bracketing the dot, so that it cannot be accidentally clicked or auto-linked when pasted into notes, tickets, or chat. A basic hygiene habit for anyone handling indicators by hand.",
	"security-event": "NIST SP 800-61's term for any observable occurrence in a system or network: a login, a DNS query, a file write. Most collected data is events, with no claim of maliciousness attached.",
	"security-alert": "An event flagged as potentially unwanted or unauthorized, whether by a signature match or an anomaly rule. An alert is a claim worth an analyst's attention, not yet a confirmed compromise.",
	"security-incident": "NIST SP 800-61's term for a confirmed violation, or imminent threat of violation, of security policy that affects the confidentiality, integrity, or availability of business data. An alert becomes an incident once an analyst verifies it as a true positive.",
	"high-fidelity-alert": "An alert whose underlying logic is trusted enough that little or no additional triage is needed before acting on it, typically because it matches a well-sourced indicator of known-bad activity rather than a statistical deviation from normal.",
	"veris": "Vocabulary for Event Recording and Incident Sharing - a classification schema built around four elements (actor, action, asset, attribute) that together describe who did what to which asset and how it was affected. Maintained by Verizon and used as the collection format behind the annual Data Breach Investigations Report.",
	"nciss": "National Cyber Incident Scoring System - CISA's weighted scoring model for incident severity, built on NIST SP 800-61's categories (functional impact, information impact, recoverability, and others) and collapsed into a single 0-100 score mapped to a priority level from baseline to emergency.",
	"incident-management-system": "The system where a SOC tracks and works confirmed incidents as cases, distinct from generic help-desk ticketing by security-specific features: indicator storage integrated with a threat intelligence platform, case templates that encode playbooks, and tagging aligned to frameworks like the kill chain. TheHive is a widely used open-source example.",
	"case-playbook": "A pre-built template applied to a new case that generates the set of tasks an analyst must complete before the case can close, ensuring every incident of a given type (phishing, malware, and so on) gets the same thorough investigation regardless of who is assigned it.",
	"observable": "In an incident management system, a piece of data attached to a case during investigation: an IP, hash, domain, or username. An observable can be flagged as an indicator of compromise and pushed to a threat intelligence platform, feeding future detection.",
	"cvss": "Common Vulnerability Scoring System - an industry-standard formula that scores a vulnerability's theoretical severity from 0 to 10 based on properties like attack complexity and impact. The Base score, the version almost everyone actually uses, deliberately excludes whether the vulnerability is being exploited or how exposed a given organization actually is.",
	"epss": "Exploit Prediction Scoring System - a FIRST-maintained machine learning model that estimates the probability a given CVE will be exploited in the wild within the next 30 days, published daily as a 0-1 score with a percentile ranking, trained on real-world exploitation telemetry rather than theoretical severity.",
	"kev-catalog": "CISA's Known Exploited Vulnerabilities catalog, a list of CVEs CISA has confirmed are being actively exploited in the wild, with federal remediation deadlines attached. Unlike CVSS or EPSS, KEV membership is not a score or a prediction, it is a documented fact.",
	"kerberos": "The default authentication protocol in Active Directory, built on time-limited, cryptographically signed tickets rather than repeated password checks. A client proves its identity once to a Key Distribution Center and then presents tickets, not credentials, to every service it accesses afterward.",
	"ntlm": "NT LAN Manager, Windows' legacy challenge-response authentication protocol. Still active as a fallback whenever Kerberos cannot be used (no line of sight to a domain controller, access by IP address, workgroup machines), and the mechanism behind pass-the-hash and NTLM relay attacks because the hash itself is sufficient to authenticate.",
	"kdc": "Key Distribution Center - the Active Directory service, running on every domain controller, that issues and validates Kerberos tickets. It has two roles bundled together: the Authentication Service (AS) that issues TGTs, and the Ticket Granting Service (TGS) that issues service tickets against a valid TGT.",
	"kerberos-realm": "The logical group of machines that share one Kerberos authentication database, the scope within which a ticket issued by one KDC is trusted. Kerberos is an open protocol predating Active Directory; on a Windows network, a realm and a domain are the same thing under two names, which is why 'domain controller' and 'KDC' are used interchangeably.",
	"kerberos-preauth": "The cryptographic proof-of-password step in the AS-REQ: the client encrypts a timestamp with a key derived from its own password, and the KDC, deriving the same key from the account's stored hash, only issues an AS-REP if that timestamp decrypts correctly and falls within the allowed clock skew. Disabling it on an account (UF_DONT_REQUIRE_PREAUTH) is what AS-REP Roasting exploits.",
	"pac": "Privileged Attribute Certificate, a signed data structure embedded in every Kerberos TGT and service ticket, carrying the account's SID, group memberships (including SID History), and other authorization data the target service reads to decide access, without ever querying Active Directory directly. Because the PAC is what a target actually trusts for authorization, forged or edited PAC contents, not just a valid-looking ticket, are what techniques like Golden and Diamond Tickets are ultimately manipulating.",
	"spn": "Service Principal Name, the identifier a Kerberos client names in a TGS-REQ to ask for a ticket to a specific service, in the form serviceclass/host:port/servicename (e.g. MSSQLSvc/sql01.corp.com:1433). Stored in the servicePrincipalName attribute on the user or computer account that runs the service, and must be unique domain-wide, duplicate SPNs break Kerberos authentication to both accounts that share one. Any account with at least one SPN registered can have a service ticket requested for it by any authenticated user, which is the precondition Kerberoasting depends on.",
	"kerberoasting": "An attack that abuses Kerberos's own design: any authenticated domain user can request a service ticket for any account with a registered Service Principal Name, and that ticket is encrypted with a key derived from the service account's password. The attacker takes the ticket offline and cracks it without ever touching the target account or triggering a lockout.",
	"evtx": "The binary XML file format Windows uses to store event logs, one file per channel (Security.evtx, System.evtx, and a large tree of Applications and Services Logs channels), typically under C:/Windows/System32/winevt/Logs. What subcategories actually get written into a channel is controlled by the Advanced Audit Policy, not just the channel's existence.",
	"ntlm-relay": "An attack where a captured NTLM authentication attempt is forwarded live to a second target instead of cracked, letting the attacker authenticate as the coerced identity against whatever the relay target accepts NTLM for. Coercion techniques like PetitPotam force a machine account to authenticate somewhere the attacker controls, and relaying that to AD CS web enrollment can turn a single coerced machine into a domain-compromising certificate.",
	"sysmon": "System Monitor, a free Sysinternals driver and service that logs far richer endpoint telemetry than native Windows auditing: full process command lines, network connections, named pipe activity, DNS queries, and raw registry changes, written to its own Microsoft-Windows-Sysmon/Operational channel and configured through an XML rule file instead of Group Policy audit settings.",
	"waf": "Web Application Firewall, a filtering layer placed in front of a web application that inspects incoming requests against signatures and rules for known attack patterns (SQL injection syntax, path traversal sequences, and similar), blocking or logging matches before they reach the application itself. It confirms that a request looked like an attack; it has no visibility into what the application or database actually did in response.",
	"aitm": "Adversary-in-the-Middle - a phishing technique where the attacker's infrastructure proxies the victim's login session live against the real identity provider, capturing not just a password but the resulting authenticated session token, including one that has already satisfied MFA. This is why a successful MFA challenge on a phished sign-in doesn't prove the sign-in was legitimate, the MFA prompt the user approved was real, it just wasn't for their own session.",
	"zero-trust": "A security model built on the principle that no request should be trusted by default regardless of where it originates, including from inside a corporate network. Every request is verified explicitly (identity, device posture, and context) and granted only the minimum access it needs, replacing the older assumption that anything already inside a network boundary could be trusted.",
	"ztna": "Zero Trust Network Access - a replacement for traditional VPN remote access that grants per-application, per-request access instead of a broad network-level tunnel. A compromised ZTNA session can reach only the specific application it was authorized for, not every host reachable on a flat internal network the way a compromised VPN session could.",
	"mfa": "Multi-Factor Authentication - requiring more than one form of proof (something you know, something you have, something you are) before granting access, so a stolen password alone isn't enough to authenticate.",
	"conditional-access": "A policy engine (most commonly associated with Microsoft Entra ID) that evaluates a sign-in's identity, device compliance, location, and risk signals in real time and decides whether to allow, challenge with MFA, or block the request, rather than granting access on a valid password alone.",
	"casb": "Cloud Access Security Broker - a control point between an organization's users and the SaaS applications they use, giving visibility into OAuth grants, data movement, and app usage that would otherwise happen entirely outside on-prem monitoring. Coverage is limited to SaaS apps the organization has actually onboarded or discovered; shadow IT nobody registered stays invisible by definition.",
	"cspm": "Cloud Security Posture Management - tooling that continuously scans a cloud provider's control plane (IAM policies, storage bucket permissions, network exposure) for misconfigurations. It produces a point-in-time state snapshot, not real-time behavioral telemetry, so it tells you what's exposed, not who touched it.",
	"sspm": "SaaS Security Posture Management - the CSPM equivalent for SaaS platforms themselves (Microsoft 365, Google Workspace, Salesforce), auditing configuration drift, excessive permissions, and third-party app access inside the SaaS tenant rather than a cloud provider's infrastructure.",
	"mdi": "Microsoft Defender for Identity - an identity-layer sensor deployed on domain controllers that inspects Kerberos and NTLM traffic directly, giving it visibility into protocol-level abuse (Kerberoasting, DCSync, coercion attempts) that generic authentication logging alone doesn't capture.",
	"auditd": "The Linux Audit Framework, the closest Linux equivalent to Windows' Security event log: kernel-level hooks that intercept syscalls and file access, configured with auditctl rules (file watches or syscall rules), logged to /var/log/audit/audit.log, and queried with ausearch and aureport rather than Event Viewer.",
	"syslog-facility": "A numeric code in the syslog protocol (RFC 5424) identifying which subsystem generated a log message, such as auth/authpriv for login and privilege events, cron for scheduled jobs, or daemon for background services. Facility plus severity is what a log router like rsyslog or syslog-ng uses to decide where a message ends up, the rough Linux equivalent of a Windows event channel.",
	"lsass": "Local Security Authority Subsystem Service, the Windows process that enforces security policy and holds the authentication material for every logged-on session in memory: NTLM hashes, Kerberos tickets, and sometimes plaintext credentials. The single highest-value process on a live Windows machine, and the reason credential-theft tools like Mimikatz exist.",
	"ntds-dit": "The Active Directory database file (default C:/Windows/NTDS/ntds.dit) present on every domain controller, holding every object in the domain including the password hash for every domain account. The single highest-value file in an Active Directory environment.",
	"krbtgt": "The disabled-by-default Active Directory account whose password hash is used to encrypt and sign every Kerberos ticket issued in the domain. Compromising its hash allows forging a fully valid Ticket Granting Ticket offline for any user and any group membership, the Golden Ticket attack, without ever generating a domain controller authentication event.",
	"dcsync": "An attack that abuses the Directory Replication Service protocol domain controllers legitimately use to replicate with each other, requesting a domain controller send password data as though the requester were itself a domain controller. Any account holding Replicating Directory Changes rights can run it, and it retrieves the krbtgt hash the same way it retrieves any other account's.",
	"unified-kill-chain": "Paul Pols' 2017 merge of the Cyber Kill Chain, MITRE ATT&CK, and the Diamond Model into 18 phases grouped into three stages: In (initial foothold), Through (network propagation), and Out (action on objectives). Built to model modern intrusions that loop and pivot instead of marching through seven phases once.",
	"attack-tree": "A goal decomposition technique, formalized by Bruce Schneier in 1999, that breaks an attacker's objective into sub-goals down to concrete leaf attacks. Each node can be an AND gate (every child required) or an OR gate (any one child suffices), which makes the logical structure of an attack, not just its steps, explicit.",
	"ooda-loop": "John Boyd's decision cycle: Observe, Orient, Decide, Act, repeating continuously. Boyd's central claim was that whoever cycles through OODA faster than their opponent controls the engagement, which makes tempo itself a weapon independent of relative force size.",
	"f3ead": "Find, Fix, Finish, Exploit, Analyze, Disseminate: a targeting cycle that grew out of Find-Fix-Finish doctrine during counterinsurgency operations in Iraq and Afghanistan. It fuses operations and intelligence into one loop, where the Exploit and Analyze phases feed directly back into finding the next target.",
	"bow-tie": "A risk diagram, formalized by Royal Dutch Shell in the 1990s from earlier ICI safety training material, that places a single top event at the center with its causes and preventive barriers on the left and its consequences and mitigative barriers on the right. It separates the question of preventing an event from the question of limiting the damage once it happens.",
	"admiralty-code": "The NATO Intelligence Grading System (STANAG 2511, AJP-2.1), tracing back to British Admiralty Naval Intelligence practice. It pairs a letter A-F grading the source's historical reliability with a number 1-6 grading this specific report's credibility, so a rating like B2 separates who is telling you something from whether this particular thing they said checks out.",
	"active-directory": "Microsoft's directory service for Windows networks: a hierarchical, LDAP-based database that stores every user, computer, group, and policy in an enterprise as an object, and that authenticates and authorizes access across the whole network from that single store.",
	"ldap": "Lightweight Directory Access Protocol, the query and modification protocol Active Directory is built on. Any authenticated bind can typically read most of the directory by default, which is what makes AD enumeration possible with no special tooling beyond a valid credential.",
	"forest": "The actual security boundary in Active Directory, one or more domain trees sharing a single schema, Configuration partition, and Global Catalog. A domain admin in one domain is not automatically privileged elsewhere in the forest, but an Enterprise Admin or a compromised Schema Master is.",
	"domain-tree": "One or more Active Directory domains that share a contiguous DNS namespace, such as corp.com and its child emea.corp.com, joined by automatic, transitive parent-child trusts. A forest can contain more than one tree.",
	"domain": "The smallest complete unit in Active Directory's logical structure: its own partition of the directory database, its own DNS namespace, and its own default password and account lockout policy.",
	"organizational-unit": "A container inside an Active Directory domain that can be nested, have Group Policy linked to it, and have administrative permissions delegated scoped to exactly that container. Unlike the built-in Users and Computers containers, GPOs can be linked directly to an OU.",
	"domain-controller": "A server running Active Directory Domain Services. It authenticates logons, answers directory queries, and holds a copy of the domain's database in NTDS.dit, which is why compromising a domain controller usually means compromising every credential in the domain.",
	"fsmo": "Flexible Single Master Operations: five Active Directory roles (Schema Master and Domain Naming Master, forest-wide; RID Master, PDC Emulator, and Infrastructure Master, per domain) pinned to a single domain controller at a time because multi-master replication cannot safely handle them.",
	"group-policy": "Configuration, from password policy to software deployment to security settings, pushed to users and computers via GPOs linked to sites, domains, or OUs and applied in that order (Local, Site, Domain, OU). Write access to a GPO is functionally code execution on every computer it applies to.",
	"security-descriptor": "The object in Active Directory that actually decides access: an owner, a DACL of ACEs granting or denying rights like read, write, or reset-password, and a SACL for auditing. Misconfigured ACEs on this descriptor, not vulnerabilities, are the basis of most modern AD attack paths.",
	"schema": "The forest-wide definition of every object class and attribute that can exist in Active Directory. Schema changes require the Schema Master FSMO role and apply to every domain in the forest.",
	"global-catalog": "A partial, read-only, forest-wide copy of every object in every domain, held by designated domain controllers. It lets a client search or resolve universal group membership across domain boundaries without waiting on a referral.",
	"sysvol": "A shared folder replicated to every domain controller in a domain, holding Group Policy templates, logon scripts, and startup scripts. Together with the Group Policy Container object in AD, SYSVOL is the half of a GPO that actually contains its files.",
	"security-principal": "Any entity Active Directory can authenticate and assign permissions to, a user, a computer, or a group, each identified by a unique SID. Access tokens are built from a security principal's own SID plus the SIDs of every group it belongs to.",
	"powerview": "A PowerShell reconnaissance tool from the PowerSploit and Empire toolchains, providing pure-PowerShell cmdlets like Get-DomainUser, Get-DomainTrust, and Get-DomainObjectAcl for enumerating Active Directory without native RSAT tooling.",
	"bloodhound": "A graph-analysis platform, fed by the SharpHound collector, that models users, groups, computers, GPOs, and ACLs as nodes and edges in a graph database, turning questions like 'shortest path to Domain Admin' into a single query instead of hours of manual correlation.",
	"adrecon": "A PowerShell-based Active Directory reconnaissance tool that extracts a broad snapshot of a domain, users, groups, computers, trusts, GPOs, and more, into a single Excel report, popular in both offensive and audit/compliance use.",
	"tiered-administration": "A model that splits administrative access into tiers by blast radius, typically Tier 0 (domain controllers, PKI, identity-sync servers, anything that can compromise the whole forest), Tier 1 (servers), and Tier 2 (workstations), with a hard rule that a higher-tier credential never logs on to a lower-tier machine. It exists specifically to stop a single compromised workstation from turning into a path to Domain Admins.",
	"laps": "Local Administrator Password Solution, a Microsoft tool (now built into Windows as Windows LAPS) that randomizes and rotates the local administrator password on every domain-joined machine, storing the current value in AD with access controlled by ACL. It removes the shared local admin password that otherwise turns compromising one workstation into free lateral movement to every other machine using the same credential.",
	"protected-users": "A built-in Active Directory group that, for its members, disables NTLM authentication, disables weaker Kerberos encryption types, blocks delegation of the account's credentials, and shortens ticket lifetimes, all enforced by the domain controller rather than relying on client-side configuration. Intended for high-value accounts where the extra restrictions are worth the reduced compatibility.",
	"adminsdholder": "A special Active Directory object whose ACL is periodically copied onto every member of a set of protected groups (Domain Admins, Enterprise Admins, and similar) by the SDProp process, overwriting any ACL changes made directly on those accounts in between. A frequently abused persistence technique adds an attacker-controlled ACE to AdminSDHolder itself so it keeps getting silently reapplied to every protected account.",
	"asrep-roasting": "An attack against accounts with Kerberos pre-authentication disabled (UF_DONT_REQUIRE_PREAUTH). Since no proof of the password is required before the KDC responds, an attacker can request an AS-REP for any such account with no credentials at all and crack the encrypted portion offline, the same offline-cracking idea as Kerberoasting but one step earlier in the exchange.",
	"timeroasting": "An attack against MS-SNTP, Microsoft's authenticated NTP extension, that abuses the fact that a client's time-sync request need not be authenticated to receive an authenticated response: the client supplies a computer account's RID, and the DC replies with a MAC computed from that account's NTLM hash, crackable offline exactly like a Kerberoasted ticket. Unlike Kerberoasting or AS-REP Roasting, it requires no domain credential and no valid username at all, only network access to a DC's NTP service.",
	"unconstrained-delegation": "A legacy Kerberos delegation setting (TRUSTED_FOR_DELEGATION) that lets a server cache a full copy of the Kerberos TGT of any user who authenticates to it, then reuse that TGT to act as that user against any other service in the domain. Compromising a machine configured this way, especially by coercing a privileged account into authenticating to it, hands over that account's TGT wholesale.",
	"rbcd": "Resource-Based Constrained Delegation: a delegation model configured on the resource side via the msDS-AllowedToActOnBehalfOfOtherIdentity attribute rather than on the front-end service. An attacker with write access to a computer object's attributes can point this at an account they control, then use the S4U2Self and S4U2Proxy Kerberos extensions to obtain a service ticket impersonating any non-protected user against that resource.",
	"constrained-delegation": "A delegation model, older than RBCD, where an administrator lists on the front-end service account exactly which back-end SPNs (msDS-AllowedToDelegateTo) it may delegate to. If configured 'with protocol transition' (TRUSTED_TO_AUTH_FOR_DELEGATION), compromising that front-end account is enough to run a full S4U2Self/S4U2Proxy chain and impersonate any non-protected user toward those specific services, no additional write access required since the trust was already configured.",
	"coercion": "A family of RPC calls (MS-EFSRPC/PetitPotam, MS-RPRN/PrinterBug, MS-DFSNM/DFSCoerce, MS-FSRVP/ShadowCoerce) that force a Windows machine, often a domain controller, to initiate outbound NTLM or Kerberos authentication toward an address the caller supplies. Coercion itself grants nothing; it's a trigger, valuable only when paired with a listener that captures or relays the resulting authentication.",
	"nopac": "A privilege escalation chaining CVE-2021-42278 (sAMAccountName spoofing, which lets an attacker rename a controlled computer account to collide with a domain controller's name minus its trailing $) and CVE-2021-42287 (a KDC PAC-lookup fallback that, unable to find the renamed-then-deleted account, retries with a trailing $ and resolves to the real DC's computer account instead). The result is a validly signed ticket carrying a domain controller's own identity, obtainable from any standard domain user with default machine account quota.",
	"zerologon": "CVE-2020-1472, a flaw in MS-NRPC's Netlogon Secure Channel setup that reuses a static, all-zero AES-CFB8 initialization vector, making a zero-filled plaintext produce zero-filled ciphertext roughly one attempt in 256. Combined with machine accounts having no login attempt limit, an attacker can spoof a Netlogon session as any computer account, including a domain controller's, and use NetrServerPasswordSet2 to reset that account's password, most usefully via a live relay straight into DCSync rather than the disruptive direct password reset.",
	"shadow-credentials": "An attack that abuses msDS-KeyCredentialLink, the attribute that stores Windows Hello for Business key-trust credentials, by writing attacker-controlled key material onto a target account. PKINIT authentication with that key then yields a valid TGT, and the account's NTLM hash, without ever knowing or changing the account's password, and it survives a legitimate password change.",
	"adcs": "Active Directory Certificate Services, Microsoft's PKI role for issuing and managing certificates inside a domain. Because a certificate can substitute for a password during Kerberos authentication via PKINIT, misconfigured certificate templates make AD CS one of the most common privilege escalation surfaces in modern Active Directory, catalogued as the growing ESC1 through ESC16 family of techniques.",
	"esc1": "The first and most common Active Directory Certificate Services escalation: a certificate template that lets a low-privileged requester supply an arbitrary Subject Alternative Name, includes a Client Authentication EKU, and grants broad enrollment rights. Requesting a certificate for an arbitrary UPN, such as a Domain Admin, and authenticating with it via PKINIT is enough to obtain that account's TGT.",
	"certipy": "A Python tool for enumerating and abusing Active Directory Certificate Services from Linux or Windows, covering certificate template misconfigurations (the ESC family), NTLM relay to AD CS endpoints, and Shadow Credentials, without requiring the Windows-only tooling AD CS abuse originally needed.",
	"rubeus": "A C# tool from the GhostPack project for raw Kerberos ticket operations: requesting, renewing, and forging tickets, harvesting TGTs from LSASS, Kerberoasting and AS-REP Roasting, and performing the S4U2Self/S4U2Proxy requests behind delegation abuse.",
	"netexec": "The actively maintained successor to CrackMapExec, which was archived in 2023. A network execution and enumeration tool for large Windows and Active Directory environments, covering authentication spraying, share enumeration, Kerberoasting and AS-REP Roasting, and direct BloodHound data collection.",
	"golden-ticket": "A forged Kerberos TGT built entirely offline once an attacker holds the krbtgt account's password hash, valid for any username and any group membership the attacker chooses, including ones that don't exist. Because it is generated offline, no domain controller authentication event marks its creation.",
	"pkinit": "Public Key Cryptography for Initial Authentication, the Kerberos extension that lets a certificate, instead of a password, prove identity during the AS-REQ/AS-REP exchange. Shadow Credentials and Active Directory Certificate Services escalation techniques both ultimately cash out through a PKINIT request.",
	"machine-account-quota": "The ms-DS-MachineAccountQuota domain attribute, defaulting to 10, that lets any authenticated user create up to that many computer accounts without any special privilege. It is what lets an attacker without existing write access to a computer object still stand up a computer account of their own to use in a Resource-Based Constrained Delegation attack.",
	"dnsadmins": "A built-in Active Directory group intended for delegated DNS record management, whose members also get management rights over the DNS server itself, including the ServerLevelPluginDll setting that tells the DNS service which DLL to load at startup. Because the DNS role is almost always installed on a domain controller and the DNS service runs as SYSTEM, DnsAdmins membership is functionally SYSTEM-on-a-DC waiting for a service restart, tracked as CVE-2021-40469 but widely treated as a feature rather than a bug.",
	"winrm": "Windows Remote Management, the SOAP-based protocol PowerShell Remoting runs over by default on TCP 5985 (HTTP) or 5986 (HTTPS). Enter-PSSession and Invoke-Command both ride on it, and by default a target only accepts a connection from an account in its local Administrators group, which is what makes it a reliable signal that a session belongs to an admin-equivalent identity.",
	"double-hop-problem": "A Kerberos behavior where a token delegated to a remote session is not, by default, allowed to authenticate onward to a third machine: the session on the second hop has your identity but not a delegatable copy of your credential, so a network request from inside it fails or falls back to an unauthenticated context. CredSSP, classic constrained delegation, or Resource-Based Constrained Delegation are the three ways to fix it, and the last one is the same primitive attackers abuse for privilege escalation.",
	"credential-guard": "A Windows virtualization-based security feature that isolates LSASS secrets into a separate, hypervisor-protected process (LsaIso.exe) rather than ordinary user-mode memory. It blocks Mimikatz's classic sekurlsa::logonpasswords and similar in-memory reads of NTLM hashes and plaintext material, though it does not stop every credential-theft technique, Kerberos ticket extraction and DPAPI-based attacks in particular still work around it.",
	"wdigest": "A legacy Windows authentication provider that, when enabled via the UseLogonCredential registry value, keeps a reversibly-encrypted copy of a logged-on user's plaintext password in LSASS memory for compatibility with older HTTP digest authentication. Disabled by default since Windows 8.1 and Server 2012 R2, but still found toggled on in older or migrated environments, at which point Mimikatz's sekurlsa::wdigest reads the plaintext password directly.",
	"dpapi": "The Data Protection API, Windows' built-in mechanism for encrypting secrets (Credential Manager entries, Windows Vault, browser-saved passwords, some private keys) tied to a specific user or machine identity rather than to application-chosen keys. Each protected secret is encrypted under a per-user master key, which is itself protected both by a key derived from the user's password and, for domain accounts, by a domain-wide backup key held by the domain controllers.",
	"sam-database": "The Security Account Manager database, a registry hive (HKLM\\SAM, backed by C:\\Windows\\System32\\config\\SAM) holding every local account's password hash on a given machine, encrypted with a machine-specific boot key stored in the SYSTEM hive. Reading it requires SYSTEM privilege or SeBackupPrivilege, and it is why local Administrator password reuse across machines turns one compromised host into many.",
	"sharpdpapi": "A C# port of Mimikatz's DPAPI functionality from the GhostPack project, purpose-built for decrypting Credential Manager entries, Windows Vault, RDCMan/RDG files, and certificates in bulk, using either a captured master key, a domain backup key, or the current user's own context.",
	"pass-the-hash": "An attack that authenticates over NTLM using a captured NTLM hash directly, without ever recovering or needing the plaintext password. It never touches Kerberos, which is also its main weakness defensively: NTLM usage is comparatively rare and easier to flag as anomalous in a Kerberos-default environment.",
	"pass-the-ticket": "An attack that reuses a captured or forged Kerberos ticket, TGT or service ticket, to authenticate as its owner without knowing any password or key. Harder to detect than Pass the Hash by default, since Kerberos is the expected authentication protocol in Active Directory and a replayed ticket looks like ordinary traffic unless the receiving system tracks ticket reuse.",
	"overpass-the-hash": "An attack that uses a captured NTLM hash (or AES key) as Kerberos long-term key material to request a real TGT from the KDC, converting a hash into full Kerberos access rather than reusing it over NTLM. Using the RC4 (NTLM) hash produces an encryption-type downgrade that's a detectable signal by itself; using an AES key instead avoids that downgrade and is specifically called Pass the Key.",
	"primary-refresh-token": "A long-lived credential Microsoft Entra ID issues to a registered, joined, or hybrid-joined device on successful sign-in, bundling proof of user authentication with proof of device compliance. Because Conditional Access policies frequently key off device compliance, a stolen PRT lets an attacker bypass those policies and MFA entirely, not just impersonate the user, which makes it one of the highest-value credentials on a hybrid-joined endpoint.",
	"ad-connect-sync-account": "The MSOL_<installationID> on-premises account Azure AD Connect (or Entra Connect Sync) creates automatically to read and write directory data during synchronization, granted the Directory Synchronization Accounts role, which carries Replicating Directory Changes rights, DCSync-equivalent, across the on-prem domain. Its plaintext credential is stored DPAPI-protected in the local ADSync.mdf database on the sync server, decryptable by anyone with local admin on that one machine, which makes the sync server a single-host shortcut to domain-wide replication rights.",
	"targeted-kerberoasting": "A variant of Kerberoasting that removes the requirement that the target account already have an SPN. An attacker with GenericAll, GenericWrite, WriteProperty, or Validated-SPN rights on an account writes a throwaway SPN onto it, requests the now-roastable service ticket, and deletes the SPN again, turning an ACL write right into a crackable ticket against an account that was never running a service in the first place.",
	"silver-ticket": "A forged Kerberos service ticket (TGS), built entirely offline from a stolen service account's password hash rather than krbtgt. Limited to whatever service that account runs, but unlike a Golden Ticket it is presented directly to the target service and never touches a domain controller, so no AS-REQ or TGS-REQ is ever logged for it.",
	"diamond-ticket": "A Kerberos ticket forgery technique that starts from a real TGT obtained through a normal AS-REQ/AS-REP exchange, decrypts it with the krbtgt hash, modifies fields like group membership, and re-encrypts it with the same hash. Because the ticket originated from an actual domain controller, it carries correct Kerberos policy values and PAC structure, evading Golden Ticket detections that flag artifacts like an unrealistic ten-year lifetime.",
	"sapphire-ticket": "A Kerberos ticket forgery technique that goes further than a Diamond Ticket: instead of editing a PAC's fields directly, it obtains an already-legitimate PAC for a privileged account via an S4U2Self-plus-U2U request, then transplants that real PAC into a low-privileged user's own real TGT, re-encrypted with the krbtgt hash. Because the PAC itself was never hand-edited, only relocated, it eliminates the AD-correlation mismatches that catch Diamond Tickets, though the PAC it transplants is a service-ticket PAC missing the Requestor and Attributes structures Microsoft's KB5008380 patch requires in a TGT, which is what still catches it on fully patched domain controllers.",
	"skeleton-key": "An in-memory patch to LSASS on a domain controller that installs a single attacker-chosen master password valid for every account in the domain, alongside each account's real password, and downgrades Kerberos encryption to RC4 to make the patch work. Requires Domain Admin rights to install and does not survive a DC reboot.",
	"dsrm": "Directory Services Restore Mode, a special boot mode for repairing a domain controller's AD database, with its own local Administrator account and password set at DC promotion and rarely rotated afterward. With the DsrmAdminLogonBehavior registry value set to 2, that account can authenticate over the network like an ordinary local admin, a persistence backdoor that survives a full domain password reset because it is a local SAM account, not an AD object.",
	"custom-ssp": "A Security Support Provider DLL loaded into LSASS at boot, normally used to add authentication protocols like Kerberos or NTLM. A malicious SSP registered in the Security Packages registry value, or injected live into a running LSASS, sees every credential that authenticates through it afterward in plaintext, functioning as both persistence and a standing credential-harvesting implant.",
	"inter-realm-trust-key": "A shared secret, functionally a password, established between the two domains or forests on either side of a trust and stored on both sides as an LSA secret tied to a Trusted Domain Object. A domain controller uses it to encrypt a referral (inter-realm) TGT for a user crossing into the trusted realm, and the receiving side's KDC uses the same key to validate that referral before issuing a normal service ticket.",
	"sid-history": "An attribute that lets an account carry SIDs from other domains in addition to its own, added to Windows specifically so a user migrated between domains keeps access to resources still permissioned against their old SID. Because Kerberos writes every SID from this attribute into a ticket's PAC, an attacker who can forge or modify a ticket can add a privileged SID to it directly, the ExtraSids mechanism behind child-to-parent domain escalation.",
	"sid-history-injection": "A persistence technique that writes a privileged SID directly into a controlled account's own sIDHistory attribute, rather than into a single forged ticket's ExtraSids field. Because every subsequent legitimately-issued ticket for that account carries the injected SID in its PAC automatically, the backdoor survives password resets and requires no further ticket forgery, only a one-time write that on modern domain controllers has to bypass the normal replication-only restriction on that attribute.",
	"dcshadow": "A persistence and object-manipulation technique that temporarily registers an attacker-controlled machine as a rogue domain controller within AD's replication topology, then forces a legitimate DC to pull attacker-supplied changes from it as ordinary inbound replication. Because the change arrives via MS-DRSR replication rather than a direct LDAP write, it bypasses the SACL-based auditing (like event 5136) that would normally catch that same modification.",
	"sid-filtering": "A domain controller setting that strips SIDs from a presented ticket that don't belong to the domain the ticket actually claims to originate from, the specific control meant to stop SID History abuse across a trust. Enabled by default on external and forest trusts, but disabled by default on intra-forest trusts (parent-child and tree-root), because Microsoft's own guidance treats every domain inside one forest as equally trusted already.",
	"asr-rules": "Attack Surface Reduction rules, a Microsoft Defender Antivirus feature that blocks or audits specific risky behaviors, such as processes reading LSASS memory or PSExec/WMI spawning child processes, independent of signature-based malware detection. Each rule runs in Audit or Block mode and writes its own event to the Windows Defender Operational log, event 1121 for a block and 1122 for an audit hit.",
	"mde": "Microsoft Defender for Endpoint, Microsoft's EDR platform for Windows, Linux, and macOS. It enforces Attack Surface Reduction rules and correlates process, network, and file telemetry into incident-level alerts, the endpoint half of Microsoft's detection stack, distinct from Microsoft Defender for Identity, which watches AD-specific network traffic rather than endpoints.",
	"lsa-protection": "Also called RunAsPPL, a Windows setting that runs LSASS as a Protected Process Light, restricting which processes and drivers can open a handle to it at all, enforced at the kernel level rather than through a signature or behavior rule. It provides protection similar to the LSASS-focused ASR rule, and per Microsoft's own guidance makes that rule redundant where both it and Credential Guard are already enabled.",
	"site": "Active Directory's model of physical network topology: one or more IP subnets with good connectivity between them, typically a single office or data center. A site sits outside the domain and OU containment tree entirely and can span multiple domains, but a GPO can still be linked to it directly, which is the S in LSDOU.",
}

export interface TermProps {
	concept: string
	children: React.ReactNode
}

export function Term({ concept, children }: TermProps) {
	const definition = glossary[concept.toLowerCase()]

	if (!definition) {
		// If no definition found, just return the children without tooltip
		console.warn(`No definition found for concept: ${concept}`)
		return <span className="font-semibold text-primary">{children}</span>
	}

	return (
		<Tooltip>
			<TooltipTrigger asChild>
				<span className="font-semibold text-primary underline decoration-dotted decoration-1 underline-offset-2 cursor-help hover:text-primary/80 transition-colors">
					{children}
				</span>
			</TooltipTrigger>
			<TooltipContent className="max-w-xs text-sm">
				{definition}
			</TooltipContent>
		</Tooltip>
	)
}
